import { sameRepository, validRevision, type RepositoryIdentity } from "../hosting/contract.js";
import { PullRequestError, type PullRequestObservation } from "./contract.js";
import { PullRequestDraftStore, type DraftRecord } from "./draftStore.js";

interface PublishedCandidate {
  reportId: string; projectId: string; taskId: string; state: string;
  repository: RepositoryIdentity; ref: string; candidateRevision: string;
}

interface Binding {
  id: string; projectId: string; revision: number; enabled: boolean;
  instanceId: string; repositoryId: string;
}

export interface DraftAdapter {
  repository(): Promise<RepositoryIdentity>;
  defaultBranch(repository: RepositoryIdentity): Promise<{ repository: RepositoryIdentity; ref: string; revision: string }>;
  findByBranches(repository: RepositoryIdentity, headRef: string, baseRef: string): Promise<PullRequestObservation | null>;
  createDraft(repository: RepositoryIdentity, headRef: string, baseRef: string,
    headRevision: string, title: string): Promise<PullRequestObservation>;
}

export interface PullRequestDraftCoordinatorOptions {
  effects: PullRequestDraftStore;
  publication(reportId: string): PublishedCandidate | undefined;
  /** Resolved from the frozen owner policy, never an agent request. */
  policyRequiresPr(reportId: string): boolean;
  title(taskId: string): string;
  binding(projectId: string, pinned?: { id: string; revision: number }): Binding | undefined;
  makeAdapter(binding: Binding): DraftAdapter;
  now(): string;
  effectId(): string;
}

/** The owner calls this only after exact hosting publication and PR policy admission. */
export class PullRequestDraftCoordinator {
  constructor(private readonly options: PullRequestDraftCoordinatorOptions) {}

  async create(reportId: string): Promise<DraftRecord> {
    const publication = this.options.publication(reportId);
    if (!publication || publication.state !== "confirmed" || publication.reportId !== reportId ||
        !validRevision(publication.candidateRevision)) throw new PullRequestError("publication_unavailable");
    if (!this.options.policyRequiresPr(reportId)) throw new PullRequestError("draft_not_required");
    const previous = this.options.effects.getByReportId(reportId);
    const binding = this.options.binding(publication.projectId,
      previous ? { id: previous.bindingId, revision: previous.bindingRevision } : undefined);
    if (!binding || binding.projectId !== publication.projectId || (!previous && !binding.enabled)) {
      throw new PullRequestError("pr_binding_unavailable");
    }
    const adapter = this.options.makeAdapter(binding);
    const repository = await adapter.repository();
    if (!sameRepository(repository, publication.repository) || repository.instanceId !== binding.instanceId ||
        repository.nativeId !== binding.repositoryId) throw new PullRequestError("repository_mismatch");
    const baseRef = previous?.baseRef ?? (await adapter.defaultBranch(repository)).ref;
    const proposedEffectId = previous?.effectId ?? this.options.effectId();
    const effect = this.options.effects.admit({ effectId: proposedEffectId,
      reportId, projectId: publication.projectId, taskId: publication.taskId,
      bindingId: binding.id, bindingRevision: binding.revision, repository,
      headRef: publication.ref, headRevision: publication.candidateRevision,
      baseRef, recordedAt: previous?.recordedAt ?? this.options.now() });
    const existing = await adapter.findByBranches(repository, effect.headRef, effect.baseRef);
    if (existing) return this.confirm(effect, existing);
    // A retained intent may already have reached the provider. Polling can resume
    // reconciliation, but never dispatch a second create on an unproven absence.
    if (previous || effect.effectId !== proposedEffectId) {
      this.options.effects.markUnknown(effect.effectId, this.options.now());
      throw new PullRequestError("create_outcome_unknown");
    }
    let created: PullRequestObservation | null = null;
    try {
      created = await adapter.createDraft(repository, effect.headRef, effect.baseRef,
        effect.headRevision, this.options.title(effect.taskId));
    } catch {
      created = await adapter.findByBranches(repository, effect.headRef, effect.baseRef).catch(() => null);
    }
    if (created) return this.confirm(effect, created);
    this.options.effects.markUnknown(effect.effectId, this.options.now());
    throw new PullRequestError("create_outcome_unknown");
  }

  private confirm(effect: DraftRecord, observed: PullRequestObservation): DraftRecord {
    if (!sameRepository(observed.repository, effect.repository) ||
        observed.head.ref !== effect.headRef || observed.base.ref !== effect.baseRef ||
        observed.head.revision !== effect.headRevision || !observed.draft) {
      throw new PullRequestError("draft_observation_mismatch");
    }
    return this.options.effects.confirm(effect.effectId, observed.nativeId, observed.head.revision, this.options.now());
  }
}

import { randomUUID } from "node:crypto";
import { sameRepository, type RepositoryIdentity } from "../hosting/contract.js";
import { PullRequestError, validateObservation, type PullRequestObservation } from "./contract.js";
import { PullRequestReadyStore, type ReadyRecord } from "./readyStore.js";

export interface AuthorizedReadyCandidate {
  bindingId: string;
  bindingRevision: number;
  repository: RepositoryIdentity;
  nativePrId: string;
  headRevision: string;
  baseRef: string;
  baseRevision: string;
  /** Trusted owner policy milestone, verified by the consuming workflow. */
  authorityId: string;
}

export interface ReadyAdapter {
  read(repository: RepositoryIdentity, nativeId: string): Promise<PullRequestObservation | null>;
  markReady(repository: RepositoryIdentity, nativeId: string, exactHead: string): Promise<PullRequestObservation>;
}

export interface PullRequestReadyCoordinatorOptions {
  effects: PullRequestReadyStore;
  adapter: ReadyAdapter;
  verifyAuthority(candidate: AuthorizedReadyCandidate): Promise<void>;
  now(): string;
  effectId?(): string;
}

/** Owner-authorized draft-to-ready transition; uncertain retries only observe. */
export class PullRequestReadyCoordinator {
  constructor(private readonly options: PullRequestReadyCoordinatorOptions) {}

  async markReady(candidate: AuthorizedReadyCandidate): Promise<ReadyRecord> {
    await this.options.verifyAuthority(candidate);
    const previous = this.options.effects.getByCandidate(candidate.bindingId, candidate.nativePrId, candidate.headRevision);
    const proposedEffectId = previous?.effectId ?? (this.options.effectId?.() ?? randomUUID());
    const intent = this.options.effects.admit({ ...candidate, effectId: proposedEffectId,
      recordedAt: previous?.recordedAt ?? this.options.now() });
    if (intent.state !== "preflight") return this.reconcile(intent);
    const before = await this.options.adapter.read(intent.repository, intent.nativePrId);
    if (!before) throw new PullRequestError("pr_missing");
    validateObservation(before, intent.repository, intent.nativePrId);
    if (!sameRepository(before.repository, intent.repository) || before.state !== "open" ||
        before.head.revision !== intent.headRevision || before.base.ref !== intent.baseRef ||
        before.base.revision !== intent.baseRevision) throw new PullRequestError("ready_identity_mismatch");
    if (!before.draft) return this.options.effects.confirm(intent.effectId, this.options.now());
    if (!this.options.effects.markDispatching(intent.effectId, this.options.now())) {
      return this.reconcile(intent);
    }
    try {
      const after = await this.options.adapter.markReady(intent.repository, intent.nativePrId, intent.headRevision);
      if (this.readyIdentity(intent, after)) return this.options.effects.confirm(intent.effectId, this.options.now());
    } catch { /* A response can be lost after the write; reconcile by read. */ }
    return this.reconcile(intent);
  }

  private async reconcile(intent: ReadyRecord): Promise<ReadyRecord> {
    try {
      const observed = await this.options.adapter.read(intent.repository, intent.nativePrId);
      if (observed && this.readyIdentity(intent, observed)) {
        return this.options.effects.confirm(intent.effectId, this.options.now());
      }
    } catch { /* An invalid or unreadable observation cannot confirm the effect. */ }
    this.options.effects.markUnknown(intent.effectId, this.options.now());
    throw new PullRequestError("ready_outcome_unknown");
  }

  private readyIdentity(intent: ReadyRecord, observed: PullRequestObservation): boolean {
    validateObservation(observed, intent.repository, intent.nativePrId);
    return observed.state === "open" && !observed.draft &&
      observed.head.revision === intent.headRevision && observed.base.ref === intent.baseRef &&
      observed.base.revision === intent.baseRevision;
  }
}

import { randomUUID } from "node:crypto";
import { sameRepository, type RepositoryIdentity } from "../hosting/contract.js";
import { PullRequestError, requestExactMerge, validateObservation, type PullRequestAdapter } from "./contract.js";
import { PullRequestMergeStore, type MergeRecord } from "./mergeStore.js";

export interface AuthorizedMergeCandidate {
  bindingId: string;
  bindingRevision: number;
  repository: RepositoryIdentity;
  nativePrId: string;
  headRevision: string;
  baseRef: string;
  baseRevision: string;
  /** Durable Human decision proved by the owner workflow, not a client claim. */
  decisionId: string;
  actorId: string;
}

export interface PullRequestMergeCoordinatorOptions {
  effects: PullRequestMergeStore;
  adapter: PullRequestAdapter;
  /** The consuming owner workflow validates current candidate, decision and binding. */
  verifyAuthority(candidate: AuthorizedMergeCandidate): Promise<void>;
  now(): string;
  effectId?(): string;
}

/** One merge effect for one owner-approved candidate; restart recovery only reads. */
export class PullRequestMergeCoordinator {
  constructor(private readonly options: PullRequestMergeCoordinatorOptions) {}

  async merge(candidate: AuthorizedMergeCandidate): Promise<MergeRecord> {
    await this.options.verifyAuthority(candidate);
    const previous = this.options.effects.getByCandidate(candidate.bindingId, candidate.nativePrId, candidate.headRevision);
    const proposedEffectId = previous?.effectId ?? (this.options.effectId?.() ?? randomUUID());
    const intent = this.options.effects.admit({ ...candidate, effectId: proposedEffectId,
      recordedAt: previous?.recordedAt ?? this.options.now() });
    if (previous || intent.effectId !== proposedEffectId) {
      const observed = await this.options.adapter.read(intent.repository, intent.nativePrId).catch(() => null);
      if (observed) {
        validateObservation(observed, intent.repository, intent.nativePrId);
        if (observed.state === "merged" && observed.head.revision === intent.headRevision &&
            observed.mergedRevision === intent.headRevision) {
          return this.options.effects.confirm(intent.effectId, observed.mergedRevision, this.options.now());
        }
      }
      this.options.effects.markUnknown(intent.effectId, this.options.now());
      throw new PullRequestError("merge_outcome_unknown");
    }
    try {
      const observed = await requestExactMerge(this.options.adapter, { repository: intent.repository,
        nativeId: intent.nativePrId, headRevision: intent.headRevision, baseRef: intent.baseRef,
        baseRevision: intent.baseRevision,
        strategy: "fast-forward-only", requiredHumanActorId: intent.actorId });
      if (!sameRepository(observed.repository, intent.repository) || observed.mergedRevision !== intent.headRevision) {
        throw new PullRequestError("merge_outcome_unknown");
      }
      return this.options.effects.confirm(intent.effectId, observed.mergedRevision, this.options.now());
    } catch (error) {
      this.options.effects.markUnknown(intent.effectId, this.options.now());
      throw error;
    }
  }
}

import type Database from "better-sqlite3";
import { sameRepository, validBranchRef, validRevision, type RepositoryIdentity } from "../hosting/contract.js";

export interface DraftAdmission {
  effectId: string;
  reportId: string;
  projectId: string;
  taskId: string;
  bindingId: string;
  bindingRevision: number;
  repository: RepositoryIdentity;
  headRef: string;
  headRevision: string;
  baseRef: string;
  recordedAt: string;
}

export interface DraftRecord extends DraftAdmission {
  state: "pending" | "unknown" | "confirmed";
  nativePrId?: string;
  updatedAt: string;
}

export class PullRequestDraftStore {
  constructor(private readonly sqlite: Database.Database) {}

  admit(input: DraftAdmission): DraftRecord {
    validate(input);
    return this.sqlite.transaction(() => {
      const previous = this.getByReportId(input.reportId);
      if (previous) {
        if (sameIntent(previous, input)) return previous;
        throw new Error("pr_draft_identity_conflict");
      }
      this.sqlite.prepare(`INSERT INTO pr_draft_effect (effect_id, report_id, project_id, task_id,
        binding_id, binding_revision, repository_key, head_ref, head_revision, base_ref,
        state, native_pr_id, recorded_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', NULL, ?, ?)`).run(input.effectId,
        input.reportId, input.projectId, input.taskId, input.bindingId, input.bindingRevision,
        JSON.stringify(input.repository), input.headRef, input.headRevision, input.baseRef,
        input.recordedAt, input.recordedAt);
      return this.getByReportId(input.reportId)!;
    })();
  }

  getByReportId(reportId: string): DraftRecord | undefined {
    const row = this.sqlite.prepare(`SELECT * FROM pr_draft_effect WHERE report_id = ?`).get(reportId) as Row | undefined;
    return row ? fromRow(row) : undefined;
  }

  get(effectId: string): DraftRecord | undefined {
    const row = this.sqlite.prepare(`SELECT * FROM pr_draft_effect WHERE effect_id = ?`).get(effectId) as Row | undefined;
    return row ? fromRow(row) : undefined;
  }

  unresolved(): DraftRecord[] {
    return (this.sqlite.prepare(`SELECT * FROM pr_draft_effect WHERE state != 'confirmed'
      ORDER BY recorded_at, effect_id`).all() as Row[]).map(fromRow);
  }

  markUnknown(effectId: string, at: string): void {
    const updated = this.sqlite.prepare(`UPDATE pr_draft_effect SET state = 'unknown', updated_at = ?
      WHERE effect_id = ? AND state = 'pending'`).run(at, effectId);
    if (updated.changes !== 1 && !this.get(effectId)) throw new Error("pr_draft_missing");
  }

  confirm(effectId: string, nativePrId: string, observedHead: string, at: string): DraftRecord {
    const record = this.get(effectId);
    if (!record) throw new Error("pr_draft_missing");
    if (record.headRevision !== observedHead || !/^[1-9][0-9]{0,17}$/u.test(nativePrId)) {
      throw new Error("pr_draft_observation_mismatch");
    }
    if (record.state === "confirmed") {
      if (record.nativePrId !== nativePrId) throw new Error("pr_draft_identity_conflict");
      return record;
    }
    this.sqlite.prepare(`UPDATE pr_draft_effect SET state = 'confirmed', native_pr_id = ?, updated_at = ?
      WHERE effect_id = ? AND state IN ('pending', 'unknown')`).run(nativePrId, at, effectId);
    return this.get(effectId)!;
  }
}

interface Row {
  effect_id: string; report_id: string; project_id: string; task_id: string; binding_id: string;
  binding_revision: number; repository_key: string; head_ref: string; head_revision: string;
  base_ref: string; state: DraftRecord["state"]; native_pr_id: string | null;
  recorded_at: string; updated_at: string;
}

function fromRow(row: Row): DraftRecord {
  return { effectId: row.effect_id, reportId: row.report_id, projectId: row.project_id,
    taskId: row.task_id, bindingId: row.binding_id, bindingRevision: row.binding_revision,
    repository: JSON.parse(row.repository_key) as RepositoryIdentity,
    headRef: row.head_ref, headRevision: row.head_revision, baseRef: row.base_ref,
    state: row.state, ...(row.native_pr_id ? { nativePrId: row.native_pr_id } : {}),
    recordedAt: row.recorded_at, updatedAt: row.updated_at };
}

function sameIntent(record: DraftRecord, input: DraftAdmission): boolean {
  return record.reportId === input.reportId && record.projectId === input.projectId &&
    record.taskId === input.taskId && record.bindingId === input.bindingId &&
    record.bindingRevision === input.bindingRevision && sameRepository(record.repository, input.repository) &&
    record.headRef === input.headRef && record.headRevision === input.headRevision &&
    record.baseRef === input.baseRef;
}

function validate(input: DraftAdmission): void {
  const id = /^[A-Za-z0-9._:-]{1,128}$/u;
  if (![input.effectId, input.reportId, input.projectId, input.taskId, input.bindingId].every((value) => id.test(value)) ||
      !Number.isSafeInteger(input.bindingRevision) || input.bindingRevision < 1 ||
      !input.repository.provider || !input.repository.instanceId || !input.repository.nativeId ||
      !validBranchRef(input.headRef) || !validBranchRef(input.baseRef) || !validRevision(input.headRevision) ||
      !Number.isFinite(Date.parse(input.recordedAt))) throw new Error("pr_draft_invalid");
}

import type Database from "better-sqlite3";
import { sameRepository, validBranchRef, validRevision, type RepositoryIdentity } from "../hosting/contract.js";

export interface ReadyAdmission {
  effectId: string;
  bindingId: string;
  bindingRevision: number;
  repository: RepositoryIdentity;
  nativePrId: string;
  headRevision: string;
  baseRef: string;
  baseRevision: string;
  authorityId: string;
  recordedAt: string;
}

export interface ReadyRecord extends ReadyAdmission {
  state: "preflight" | "pending" | "unknown" | "confirmed";
  updatedAt: string;
}

/** One owner-admitted readiness effect per exact candidate. */
export class PullRequestReadyStore {
  constructor(private readonly sqlite: Database.Database) {}

  admit(input: ReadyAdmission): ReadyRecord {
    validate(input);
    return this.sqlite.transaction(() => {
      const existing = this.getByCandidate(input.bindingId, input.nativePrId, input.headRevision);
      if (existing) {
        if (sameIntent(existing, input)) return existing;
        throw new Error("pr_ready_identity_conflict");
      }
      this.sqlite.prepare(`INSERT INTO pr_ready_effect (effect_id, binding_id, binding_revision,
        repository_key, native_pr_id, head_revision, base_ref, base_revision, authority_id,
        state, recorded_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'preflight', ?, ?)`).run(input.effectId,
        input.bindingId, input.bindingRevision, JSON.stringify(input.repository), input.nativePrId,
        input.headRevision, input.baseRef, input.baseRevision, input.authorityId,
        input.recordedAt, input.recordedAt);
      return this.get(input.effectId)!;
    })();
  }

  get(effectId: string): ReadyRecord | undefined {
    const row = this.sqlite.prepare(`SELECT * FROM pr_ready_effect WHERE effect_id = ?`).get(effectId) as Row | undefined;
    return row ? fromRow(row) : undefined;
  }

  getByCandidate(bindingId: string, nativePrId: string, headRevision: string): ReadyRecord | undefined {
    const row = this.sqlite.prepare(`SELECT * FROM pr_ready_effect
      WHERE binding_id = ? AND native_pr_id = ? AND head_revision = ?`).get(bindingId, nativePrId, headRevision) as Row | undefined;
    return row ? fromRow(row) : undefined;
  }

  unresolved(): ReadyRecord[] {
    return (this.sqlite.prepare(`SELECT * FROM pr_ready_effect WHERE state != 'confirmed'
      ORDER BY recorded_at, effect_id`).all() as Row[]).map(fromRow);
  }

  /** A single caller wins the durable boundary immediately before a possible write. */
  markDispatching(effectId: string, at: string): boolean {
    return this.sqlite.prepare(`UPDATE pr_ready_effect SET state = 'pending', updated_at = ?
      WHERE effect_id = ? AND state = 'preflight'`).run(at, effectId).changes === 1;
  }

  markUnknown(effectId: string, at: string): void {
    const updated = this.sqlite.prepare(`UPDATE pr_ready_effect SET state = 'unknown', updated_at = ?
      WHERE effect_id = ? AND state = 'pending'`).run(at, effectId);
    if (updated.changes !== 1 && !this.get(effectId)) throw new Error("pr_ready_missing");
  }

  confirm(effectId: string, at: string): ReadyRecord {
    const record = this.get(effectId);
    if (!record) throw new Error("pr_ready_missing");
    if (record.state === "confirmed") return record;
    this.sqlite.prepare(`UPDATE pr_ready_effect SET state = 'confirmed', updated_at = ?
      WHERE effect_id = ? AND state IN ('preflight', 'pending', 'unknown')`).run(at, effectId);
    return this.get(effectId)!;
  }
}

interface Row {
  effect_id: string; binding_id: string; binding_revision: number; repository_key: string;
  native_pr_id: string; head_revision: string; base_ref: string; base_revision: string;
  authority_id: string; state: ReadyRecord["state"]; recorded_at: string; updated_at: string;
}

function fromRow(row: Row): ReadyRecord {
  return { effectId: row.effect_id, bindingId: row.binding_id, bindingRevision: row.binding_revision,
    repository: JSON.parse(row.repository_key) as RepositoryIdentity, nativePrId: row.native_pr_id,
    headRevision: row.head_revision, baseRef: row.base_ref, baseRevision: row.base_revision,
    authorityId: row.authority_id, state: row.state, recordedAt: row.recorded_at, updatedAt: row.updated_at };
}

function sameIntent(record: ReadyRecord, input: ReadyAdmission): boolean {
  return record.bindingId === input.bindingId && record.bindingRevision === input.bindingRevision &&
    sameRepository(record.repository, input.repository) && record.nativePrId === input.nativePrId &&
    record.headRevision === input.headRevision && record.baseRef === input.baseRef &&
    record.baseRevision === input.baseRevision && record.authorityId === input.authorityId;
}

function validate(input: ReadyAdmission): void {
  const id = /^[A-Za-z0-9._:-]{1,128}$/u;
  if (![input.effectId, input.bindingId, input.nativePrId, input.authorityId].every((value) => id.test(value)) ||
      !Number.isSafeInteger(input.bindingRevision) || input.bindingRevision < 1 ||
      !input.repository.provider || !input.repository.instanceId || !input.repository.nativeId ||
      !validRevision(input.headRevision) || !validBranchRef(input.baseRef) || !validRevision(input.baseRevision) ||
      !Number.isFinite(Date.parse(input.recordedAt))) throw new Error("pr_ready_invalid");
}

import type Database from "better-sqlite3";
import { sameRepository, validBranchRef, validRevision, type RepositoryIdentity } from "../hosting/contract.js";

export interface MergeAdmission {
  effectId: string;
  bindingId: string;
  bindingRevision: number;
  repository: RepositoryIdentity;
  nativePrId: string;
  headRevision: string;
  baseRef: string;
  baseRevision: string;
  /** Owner-verified durable Human decision, supplied by the consuming workflow. */
  decisionId: string;
  actorId: string;
  recordedAt: string;
}

export interface MergeRecord extends MergeAdmission {
  state: "pending" | "unknown" | "confirmed";
  mergedRevision?: string;
  updatedAt: string;
}

export class PullRequestMergeStore {
  constructor(private readonly sqlite: Database.Database) {}

  admit(input: MergeAdmission): MergeRecord {
    validate(input);
    return this.sqlite.transaction(() => {
      const existing = this.getByCandidate(input.bindingId, input.nativePrId, input.headRevision);
      if (existing) {
        if (sameIntent(existing, input)) return existing;
        throw new Error("pr_merge_identity_conflict");
      }
      this.sqlite.prepare(`INSERT INTO pr_merge_effect (effect_id, binding_id, binding_revision,
        repository_key, native_pr_id, head_revision, base_ref, base_revision, decision_id, actor_id,
        state, merged_revision, recorded_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', NULL, ?, ?)`).run(input.effectId,
        input.bindingId, input.bindingRevision, JSON.stringify(input.repository), input.nativePrId,
        input.headRevision, input.baseRef, input.baseRevision, input.decisionId, input.actorId, input.recordedAt, input.recordedAt);
      return this.get(input.effectId)!;
    })();
  }

  get(effectId: string): MergeRecord | undefined {
    const row = this.sqlite.prepare(`SELECT * FROM pr_merge_effect WHERE effect_id = ?`).get(effectId) as Row | undefined;
    return row ? fromRow(row) : undefined;
  }

  getByCandidate(bindingId: string, nativePrId: string, headRevision: string): MergeRecord | undefined {
    const row = this.sqlite.prepare(`SELECT * FROM pr_merge_effect
      WHERE binding_id = ? AND native_pr_id = ? AND head_revision = ?`).get(bindingId, nativePrId, headRevision) as Row | undefined;
    return row ? fromRow(row) : undefined;
  }

  unresolved(): MergeRecord[] {
    return (this.sqlite.prepare(`SELECT * FROM pr_merge_effect WHERE state != 'confirmed'
      ORDER BY recorded_at, effect_id`).all() as Row[]).map(fromRow);
  }

  markUnknown(effectId: string, at: string): void {
    const updated = this.sqlite.prepare(`UPDATE pr_merge_effect SET state = 'unknown', updated_at = ?
      WHERE effect_id = ? AND state = 'pending'`).run(at, effectId);
    if (updated.changes !== 1 && !this.get(effectId)) throw new Error("pr_merge_missing");
  }

  confirm(effectId: string, mergedRevision: string, at: string): MergeRecord {
    const record = this.get(effectId);
    if (!record) throw new Error("pr_merge_missing");
    if (record.headRevision !== mergedRevision) throw new Error("pr_merge_observation_mismatch");
    if (record.state === "confirmed") return record;
    this.sqlite.prepare(`UPDATE pr_merge_effect SET state = 'confirmed', merged_revision = ?, updated_at = ?
      WHERE effect_id = ? AND state IN ('pending', 'unknown')`).run(mergedRevision, at, effectId);
    return this.get(effectId)!;
  }
}

interface Row {
  effect_id: string; binding_id: string; binding_revision: number; repository_key: string;
  native_pr_id: string; head_revision: string; base_ref: string; base_revision: string; decision_id: string;
  actor_id: string; state: MergeRecord["state"]; merged_revision: string | null;
  recorded_at: string; updated_at: string;
}

function fromRow(row: Row): MergeRecord {
  return { effectId: row.effect_id, bindingId: row.binding_id, bindingRevision: row.binding_revision,
    repository: JSON.parse(row.repository_key) as RepositoryIdentity, nativePrId: row.native_pr_id,
    headRevision: row.head_revision, baseRef: row.base_ref, baseRevision: row.base_revision, decisionId: row.decision_id,
    actorId: row.actor_id, state: row.state,
    ...(row.merged_revision ? { mergedRevision: row.merged_revision } : {}),
    recordedAt: row.recorded_at, updatedAt: row.updated_at };
}

function sameIntent(record: MergeRecord, input: MergeAdmission): boolean {
  return record.bindingId === input.bindingId && record.bindingRevision === input.bindingRevision &&
    sameRepository(record.repository, input.repository) && record.nativePrId === input.nativePrId &&
    record.headRevision === input.headRevision && record.baseRef === input.baseRef &&
    record.baseRevision === input.baseRevision &&
    record.decisionId === input.decisionId && record.actorId === input.actorId;
}

function validate(input: MergeAdmission): void {
  const id = /^[A-Za-z0-9._:-]{1,128}$/u;
  if (![input.effectId, input.bindingId, input.nativePrId, input.decisionId, input.actorId].every((value) => id.test(value)) ||
      !Number.isSafeInteger(input.bindingRevision) || input.bindingRevision < 1 ||
      !input.repository.provider || !input.repository.instanceId || !input.repository.nativeId ||
      !validRevision(input.headRevision) || !validBranchRef(input.baseRef) || !validRevision(input.baseRevision) ||
      !Number.isFinite(Date.parse(input.recordedAt))) throw new Error("pr_merge_invalid");
}

