import { test } from "vitest";
import assert from "node:assert/strict";
import Database from "better-sqlite3";
import { PullRequestDraftStore } from "./draftStore.js";

test("draft intent survives retry, rejects changed identity and confirms only an exact observed PR", () => {
  const sqlite = new Database(":memory:");
  sqlite.exec(`CREATE TABLE pr_draft_effect (effect_id TEXT PRIMARY KEY, report_id TEXT UNIQUE,
    project_id TEXT, task_id TEXT, binding_id TEXT, binding_revision INTEGER,
    repository_key TEXT, head_ref TEXT, head_revision TEXT, base_ref TEXT,
    state TEXT, native_pr_id TEXT, recorded_at TEXT, updated_at TEXT);`);
  try {
    const store = new PullRequestDraftStore(sqlite);
    const input = { effectId: "effect-1", reportId: "report-1", projectId: "project-1", taskId: "task-1",
      bindingId: "pr-1", bindingRevision: 1,
      repository: { provider: "gitea", instanceId: "forge", nativeId: "42" },
      headRef: "refs/heads/work", headRevision: "a".repeat(40), baseRef: "refs/heads/main",
      recordedAt: "2026-10-13T00:00:00Z" };
    const first = store.admit(input);
    assert.equal(first.state, "pending");
    assert.equal(store.admit({ ...input, effectId: "retry-id" }).effectId, first.effectId);
    assert.throws(() => store.admit({ ...input, baseRef: "refs/heads/other" }), /pr_draft_identity_conflict/u);
    store.markUnknown(first.effectId, "2026-10-13T00:00:01Z");
    assert.equal(store.getByReportId("report-1")?.state, "unknown");
    assert.throws(() => store.confirm(first.effectId, "7", "b".repeat(40), "2026-10-13T00:00:02Z"),
      /pr_draft_observation_mismatch/u);
    assert.equal(store.confirm(first.effectId, "7", input.headRevision, "2026-10-13T00:00:03Z").nativePrId, "7");
  } finally { sqlite.close(); }
});

import type Database from "better-sqlite3";
import { sameRepository, validBranchRef, validRevision, type RepositoryIdentity } from "../hosting/contract.js";

export interface ReadyAdmission {
  effectId: string;
  bindingId: string;
  bindingRevision: number;
  repository: RepositoryIdentity;
  nativePrId: string;
  headRevision: string;
  baseRef: string;
  baseRevision: string;
  authorityId: string;
  recordedAt: string;
}

export interface ReadyRecord extends ReadyAdmission {
  state: "preflight" | "pending" | "unknown" | "confirmed";
  updatedAt: string;
}

/** One owner-admitted readiness effect per exact candidate. */
export class PullRequestReadyStore {
  constructor(private readonly sqlite: Database.Database) {}

  admit(input: ReadyAdmission): ReadyRecord {
    validate(input);
    return this.sqlite.transaction(() => {
      const existing = this.getByCandidate(input.bindingId, input.nativePrId, input.headRevision);
      if (existing) {
        if (sameIntent(existing, input)) return existing;
        throw new Error("pr_ready_identity_conflict");
      }
      this.sqlite.prepare(`INSERT INTO pr_ready_effect (effect_id, binding_id, binding_revision,
        repository_key, native_pr_id, head_revision, base_ref, base_revision, authority_id,
        state, recorded_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'preflight', ?, ?)`).run(input.effectId,
        input.bindingId, input.bindingRevision, JSON.stringify(input.repository), input.nativePrId,
        input.headRevision, input.baseRef, input.baseRevision, input.authorityId,
        input.recordedAt, input.recordedAt);
      return this.get(input.effectId)!;
    })();
  }

  get(effectId: string): ReadyRecord | undefined {
    const row = this.sqlite.prepare(`SELECT * FROM pr_ready_effect WHERE effect_id = ?`).get(effectId) as Row | undefined;
    return row ? fromRow(row) : undefined;
  }

  getByCandidate(bindingId: string, nativePrId: string, headRevision: string): ReadyRecord | undefined {
    const row = this.sqlite.prepare(`SELECT * FROM pr_ready_effect
      WHERE binding_id = ? AND native_pr_id = ? AND head_revision = ?`).get(bindingId, nativePrId, headRevision) as Row | undefined;
    return row ? fromRow(row) : undefined;
  }

  unresolved(): ReadyRecord[] {
    return (this.sqlite.prepare(`SELECT * FROM pr_ready_effect WHERE state != 'confirmed'
      ORDER BY recorded_at, effect_id`).all() as Row[]).map(fromRow);
  }

  /** A single caller wins the durable boundary immediately before a possible write. */
  markDispatching(effectId: string, at: string): boolean {
    return this.sqlite.prepare(`UPDATE pr_ready_effect SET state = 'pending', updated_at = ?
      WHERE effect_id = ? AND state = 'preflight'`).run(at, effectId).changes === 1;
  }

  markUnknown(effectId: string, at: string): void {
    const updated = this.sqlite.prepare(`UPDATE pr_ready_effect SET state = 'unknown', updated_at = ?
      WHERE effect_id = ? AND state = 'pending'`).run(at, effectId);
    if (updated.changes !== 1 && !this.get(effectId)) throw new Error("pr_ready_missing");
  }

  confirm(effectId: string, at: string): ReadyRecord {
    const record = this.get(effectId);
    if (!record) throw new Error("pr_ready_missing");
    if (record.state === "confirmed") return record;
    this.sqlite.prepare(`UPDATE pr_ready_effect SET state = 'confirmed', updated_at = ?
      WHERE effect_id = ? AND state IN ('preflight', 'pending', 'unknown')`).run(at, effectId);
    return this.get(effectId)!;
  }
}

interface Row {
  effect_id: string; binding_id: string; binding_revision: number; repository_key: string;
  native_pr_id: string; head_revision: string; base_ref: string; base_revision: string;
  authority_id: string; state: ReadyRecord["state"]; recorded_at: string; updated_at: string;
}

function fromRow(row: Row): ReadyRecord {
  return { effectId: row.effect_id, bindingId: row.binding_id, bindingRevision: row.binding_revision,
    repository: JSON.parse(row.repository_key) as RepositoryIdentity, nativePrId: row.native_pr_id,
    headRevision: row.head_revision, baseRef: row.base_ref, baseRevision: row.base_revision,
    authorityId: row.authority_id, state: row.state, recordedAt: row.recorded_at, updatedAt: row.updated_at };
}

function sameIntent(record: ReadyRecord, input: ReadyAdmission): boolean {
  return record.bindingId === input.bindingId && record.bindingRevision === input.bindingRevision &&
    sameRepository(record.repository, input.repository) && record.nativePrId === input.nativePrId &&
    record.headRevision === input.headRevision && record.baseRef === input.baseRef &&
    record.baseRevision === input.baseRevision && record.authorityId === input.authorityId;
}

function validate(input: ReadyAdmission): void {
  const id = /^[A-Za-z0-9._:-]{1,128}$/u;
  if (![input.effectId, input.bindingId, input.nativePrId, input.authorityId].every((value) => id.test(value)) ||
      !Number.isSafeInteger(input.bindingRevision) || input.bindingRevision < 1 ||
      !input.repository.provider || !input.repository.instanceId || !input.repository.nativeId ||
      !validRevision(input.headRevision) || !validBranchRef(input.baseRef) || !validRevision(input.baseRevision) ||
      !Number.isFinite(Date.parse(input.recordedAt))) throw new Error("pr_ready_invalid");
}

import { test } from "vitest";
import assert from "node:assert/strict";
import Database from "better-sqlite3";
import { PullRequestMergeStore } from "./mergeStore.js";

test("merge intent pins decision and candidate before external effect", () => {
  const sqlite = new Database(":memory:");
  sqlite.exec(`CREATE TABLE pr_merge_effect (effect_id TEXT PRIMARY KEY, binding_id TEXT,
    binding_revision INTEGER, repository_key TEXT, native_pr_id TEXT, head_revision TEXT,
    base_ref TEXT, base_revision TEXT, decision_id TEXT, actor_id TEXT, state TEXT, merged_revision TEXT,
    recorded_at TEXT, updated_at TEXT, UNIQUE(binding_id,native_pr_id,head_revision));`);
  try {
    const store = new PullRequestMergeStore(sqlite);
    const input = { effectId: "effect", bindingId: "pr", bindingRevision: 1,
      repository: { provider: "gitea", instanceId: "forge", nativeId: "42" },
      nativePrId: "7", headRevision: "a".repeat(40), baseRef: "refs/heads/main", baseRevision: "b".repeat(40),
      decisionId: "decision-1", actorId: "person-1", recordedAt: "2026-10-13T00:00:00Z" };
    assert.equal(store.admit(input).state, "pending");
    assert.equal(store.admit({ ...input, effectId: "retry" }).effectId, "effect");
    assert.throws(() => store.admit({ ...input, decisionId: "decision-2" }), /pr_merge_identity_conflict/u);
    assert.throws(() => store.admit({ ...input, baseRevision: "c".repeat(40) }), /pr_merge_identity_conflict/u);
    store.markUnknown("effect", "2026-10-13T00:00:01Z");
    assert.equal(store.get("effect")?.state, "unknown");
    assert.throws(() => store.confirm("effect", "b".repeat(40), "2026-10-13T00:00:02Z"),
      /pr_merge_observation_mismatch/u);
    assert.equal(store.confirm("effect", input.headRevision, "2026-10-13T00:00:03Z").state, "confirmed");
  } finally { sqlite.close(); }
});

import { GiteaHostingAdapter } from "../hosting/gitea.js";
import { sameRepository, validBranchRef, validRevision, type RepositoryIdentity } from "../hosting/contract.js";
import { hostingBaseUrl, validGiteaLocatorComponent } from "../hosting/scope.js";
import { PullRequestError, type PullRequestAdapter, type PullRequestObservation,
  type PullRequestReview } from "./contract.js";

export interface GiteaPullRequestConfiguration {
  instanceId: string;
  baseUrl: string;
  owner: string;
  name: string;
  token(): Promise<string>;
  fetcher?: typeof fetch;
}

/** Owner-private Gitea Community PR port. No Issues or Actions route is admitted. */
export class GiteaPullRequestAdapter implements PullRequestAdapter {
  private readonly base: URL;
  private readonly prefix: string;
  private readonly fetcher: typeof fetch;
  private readonly hosting: GiteaHostingAdapter;

  constructor(private readonly config: GiteaPullRequestConfiguration) {
    const base = hostingBaseUrl(config.baseUrl);
    if (!base || !validGiteaLocatorComponent(config.owner) || !validGiteaLocatorComponent(config.name) ||
        !/^[a-zA-Z0-9._/-]{1,128}$/u.test(config.instanceId)) throw new PullRequestError("invalid_instance_scope");
    this.base = base;
    this.prefix = `api/v1/repos/${encodeURIComponent(config.owner)}/${encodeURIComponent(config.name)}`;
    this.fetcher = config.fetcher ?? fetch;
    this.hosting = new GiteaHostingAdapter(config);
  }

  async repository(): Promise<RepositoryIdentity> {
    try { return await this.hosting.repository(); }
    catch (error) { throw translateHosting(error); }
  }

  async defaultBranch(repository: RepositoryIdentity): Promise<{ repository: RepositoryIdentity; ref: string; revision: string }> {
    try { return await this.hosting.defaultBranch(repository); }
    catch (error) { throw translateHosting(error); }
  }

  async probePullRequestRead(repository: RepositoryIdentity): Promise<void> {
    await this.checkRepository(repository);
    const data = await this.request("GET", "/pulls?state=all&limit=1&page=1");
    if (!Array.isArray(data)) throw new PullRequestError("malformed_pr_list");
  }

  async read(repository: RepositoryIdentity, nativeId: string): Promise<PullRequestObservation | null> {
    await this.checkRepository(repository);
    const index = nativeIndex(nativeId);
    const data = await this.request("GET", `/pulls/${index}`);
    if (data === null) return null;
    const pull = object(data, "malformed_pr");
    const head = object(pull.head, "malformed_pr");
    const base = object(pull.base, "malformed_pr");
    if (pull.number !== index || !Number.isSafeInteger(pull.id) || Number(pull.id) < 1 ||
        typeof pull.draft !== "boolean" || typeof pull.merged !== "boolean" ||
        !["open", "closed"].includes(String(pull.state)) ||
        (pull.mergeable !== null && typeof pull.mergeable !== "boolean") ||
        !validRefInfo(head) || !validRefInfo(base) ||
        typeof pull.updated_at !== "string" || !Number.isFinite(Date.parse(pull.updated_at)) ||
        !Number.isSafeInteger(pull.comments) || Number(pull.comments) < 0 || Number(pull.comments) > 1_000_000) {
      throw new PullRequestError("malformed_pr");
    }
    if (!sameNativeRepository(head.repo, repository) || !sameNativeRepository(base.repo, repository)) {
      throw new PullRequestError("repository_mismatch");
    }
    const protectedBase = await this.hosting.protection(repository, `refs/heads/${base.ref}`).catch((error: unknown) => {
      throw translateHosting(error);
    });
    if (!protectedBase) throw new PullRequestError("base_branch_missing");
    const reviews = await this.readReviews(index);
    const checks = await this.readChecks(head.sha as string, protectedBase.requiredStatusContexts);
    const state = pull.merged ? "merged" : pull.state as "open" | "closed";
    const mergedRevision = pull.merge_commit_sha;
    if (state === "merged" && (typeof mergedRevision !== "string" || !validRevision(mergedRevision))) {
      throw new PullRequestError("merged_revision_unknown");
    }
    return {
      repository, nativeId, head: { repository, ref: `refs/heads/${head.ref}`, revision: head.sha as string },
      base: { repository, ref: `refs/heads/${base.ref}`, revision: protectedBase.revision },
      state, draft: pull.draft, mergeable: pull.mergeable as boolean | null,
      mergeStrategy: sameNativeRepository(base.repo, repository) &&
        (base.repo as Record<string, unknown>).allow_fast_forward_only_merge === true ? "fast-forward-only" : "other",
      requiredChecks: checks.required, advisoryChecks: checks.advisory, queuedMerge: "unknown",
      requiredApprovals: protectedBase.requiredApprovals,
      reviews, discussionCount: pull.comments as number,
      providerRevision: pull.updated_at,
      ...(state === "merged" ? { mergedRevision: mergedRevision as string } : {}),
      ...(safeUrl(pull.html_url, this.base) ? { url: pull.html_url as string } : {})
    };
  }

  async findByBranches(repository: RepositoryIdentity, headRef: string, baseRef: string): Promise<PullRequestObservation | null> {
    await this.checkRepository(repository);
    if (!validBranchRef(headRef) || !validBranchRef(baseRef)) throw new PullRequestError("invalid_branch_ref");
    const data = await this.request("GET", "/pulls?state=all&limit=100&page=1");
    if (!Array.isArray(data) || data.length >= 100) throw new PullRequestError("pr_lookup_incomplete");
    const matches = data.filter((item: unknown) => {
      const pull = object(item, "malformed_pr_list");
      const head = object(pull.head, "malformed_pr_list");
      const base = object(pull.base, "malformed_pr_list");
      return sameNativeRepository(head.repo, repository) && sameNativeRepository(base.repo, repository) &&
        head.ref === headRef.slice(11) && base.ref === baseRef.slice(11);
    });
    if (matches.length > 1) throw new PullRequestError("ambiguous_pr_identity");
    if (!matches.length) return null;
    const number = object(matches[0], "malformed_pr_list").number;
    if (!Number.isSafeInteger(number) || Number(number) < 1) throw new PullRequestError("malformed_pr_list");
    return this.read(repository, String(number));
  }

  /** Caller persists the effect ID and exact branch identity before dispatch. */
  async createDraft(repository: RepositoryIdentity, headRef: string, baseRef: string,
    headRevision: string, title: string): Promise<PullRequestObservation> {
    if (!validBranchRef(headRef) || !validBranchRef(baseRef) || !validRevision(headRevision) ||
        !title.trim() || title.length > 240) throw new PullRequestError("invalid_create_request");
    const existing = await this.findByBranches(repository, headRef, baseRef);
    if (existing) {
      if (existing.head.revision !== headRevision) throw new PullRequestError("head_moved");
      return existing;
    }
    const observed = await this.hosting.branch(repository, headRef).catch((error: unknown) => { throw translateHosting(error); });
    if (observed?.revision !== headRevision) throw new PullRequestError("head_moved");
    const draftTitle = /^\s*(?:WIP:|\[WIP\])/iu.test(title) ? title : `WIP: ${title}`;
    try {
      await this.request("POST", "/pulls", { head: headRef.slice(11), base: baseRef.slice(11), title: draftTitle });
    } catch (error) {
      // A timeout can follow successful creation; only an exact provider read resolves it.
      const found = await this.findByBranches(repository, headRef, baseRef).catch(() => null);
      if (found?.head.revision === headRevision && found.draft) return found;
      if (error instanceof PullRequestError && error.code === "permission_denied") throw error;
      throw new PullRequestError("create_outcome_unknown");
    }
    const created = await this.findByBranches(repository, headRef, baseRef).catch(() => null);
    if (!created || !created.draft || created.head.revision !== headRevision) throw new PullRequestError("create_outcome_unknown");
    return created;
  }

  /** The owner merge path may advance a draft by removing its WIP prefix. */
  async markReady(repository: RepositoryIdentity, nativeId: string, exactHead: string): Promise<PullRequestObservation> {
    const before = await this.read(repository, nativeId);
    if (!before || before.state !== "open" || before.head.revision !== exactHead) throw new PullRequestError("head_moved");
    if (!before.draft) return before;
    const raw = object(await this.request("GET", `/pulls/${nativeIndex(nativeId)}`), "malformed_pr");
    if (typeof raw.title !== "string" || !/^\s*(?:WIP:|\[WIP\])/iu.test(raw.title)) {
      throw new PullRequestError("draft_transition_unsupported");
    }
    const title = raw.title.replace(/^\s*(?:WIP:|\[WIP\])\s*/iu, "");
    try { await this.request("PATCH", `/pulls/${nativeIndex(nativeId)}`, { title }); }
    catch { /* Reconcile a write whose response was lost. */ }
    const after = await this.read(repository, nativeId).catch(() => null);
    if (!after || after.draft || after.head.revision !== exactHead) throw new PullRequestError("ready_outcome_unknown");
    return after;
  }

  async mergeFastForward(repository: RepositoryIdentity, nativeId: string, exactHead: string): Promise<void> {
    await this.checkRepository(repository);
    if (!validRevision(exactHead)) throw new PullRequestError("invalid_merge_request");
    await this.request("POST", `/pulls/${nativeIndex(nativeId)}/merge`, { do: "fast-forward-only",
      head_commit_id: exactHead, force_merge: false, merge_when_checks_succeed: false,
      delete_branch_after_merge: false });
  }

  private async checkRepository(repository: RepositoryIdentity): Promise<void> {
    if (!sameRepository(await this.repository(), repository)) throw new PullRequestError("repository_mismatch");
  }

  private async readReviews(index: number): Promise<PullRequestReview[]> {
    const data = await this.request("GET", `/pulls/${index}/reviews?limit=100&page=1`);
    if (!Array.isArray(data) || data.length >= 100) throw new PullRequestError("review_observation_incomplete");
    return data.map((item: unknown) => {
      const review = object(item, "malformed_review");
      const user = object(review.user, "malformed_review");
      const decision = review.state === "APPROVED" ? "approved" : review.state === "REQUEST_CHANGES"
        ? "changes_requested" : review.state === "COMMENT" ? "commented" : "pending";
      const formal = decision === "approved" || decision === "changes_requested";
      if (!Number.isSafeInteger(review.id) || Number(review.id) < 1 || !Number.isSafeInteger(user.id) ||
          Number(user.id) < 1 || typeof user.login !== "string" || user.login.length > 128 ||
          typeof review.dismissed !== "boolean" || typeof review.stale !== "boolean" ||
          (formal && (typeof review.commit_id !== "string" || !validRevision(review.commit_id) ||
            typeof review.submitted_at !== "string" || !Number.isFinite(Date.parse(review.submitted_at))))) {
        throw new PullRequestError("malformed_review");
      }
      return { nativeId: String(review.id), actor: { nativeId: String(user.id), login: user.login,
        kind: user.type === "User" ? "human" as const : user.type === "Bot" ? "bot" as const : "unknown" as const },
        decision, headRevision: typeof review.commit_id === "string" && validRevision(review.commit_id) ? review.commit_id : "",
        dismissed: review.dismissed, stale: review.stale || !formal,
        submittedAt: typeof review.submitted_at === "string" && Number.isFinite(Date.parse(review.submitted_at))
          ? review.submitted_at : "" };
    });
  }

  private async readChecks(sha: string, contexts: string[]): Promise<{
    required: PullRequestObservation["requiredChecks"];
    advisory: NonNullable<PullRequestObservation["advisoryChecks"]>;
  }> {
    const data = object(await this.request("GET", `/commits/${sha}/status?limit=100&page=1`), "malformed_status");
    if (data.sha !== sha || !Array.isArray(data.statuses) || data.statuses.length >= 100 ||
        !Number.isSafeInteger(data.total_count) || Number(data.total_count) > 100) {
      throw new PullRequestError("status_observation_incomplete");
    }
    const statuses = new Map<string, string>();
    for (const item of data.statuses) {
      const status = object(item, "malformed_status");
      if (typeof status.context !== "string" || typeof status.status !== "string") throw new PullRequestError("malformed_status");
      if (!statuses.has(status.context)) statuses.set(status.context, status.status);
    }
    const required = contexts.map((context) => ({ context, state: statusState(statuses.get(context)) }));
    const advisory = [...statuses.entries()].filter(([context]) => !contexts.includes(context))
      .map(([context, state]) => ({ context, state: statusState(state) }));
    return { required, advisory };
  }

  private async request(method: "GET" | "POST" | "PATCH", suffix: string, body?: object): Promise<unknown | null> {
    let token: string;
    try { token = await this.config.token(); } catch { throw new PullRequestError("credential_unavailable"); }
    if (!token || /[\r\n]/u.test(token)) throw new PullRequestError("credential_unavailable");
    const url = new URL(`${this.prefix}${suffix}`, this.base);
    let response: Response;
    try {
      response = await this.fetcher(url, { method, headers: { Authorization: `token ${token}`,
        Accept: "application/json", ...(body ? { "Content-Type": "application/json" } : {}) },
      ...(body ? { body: JSON.stringify(body) } : {}), redirect: "error", signal: AbortSignal.timeout(10_000) });
    } catch { throw new PullRequestError("provider_unavailable"); }
    if (response.status === 401 || response.status === 403) throw new PullRequestError("permission_denied");
    if (response.status === 404) return null;
    if (response.status === 429) throw new PullRequestError("rate_limited");
    if (!response.ok) throw new PullRequestError(response.status === 409 ? "provider_conflict" : "provider_unavailable");
    if (Number(response.headers.get("content-length")) > 1_000_000) throw new PullRequestError("response_limit_exceeded");
    if (method !== "GET" && response.status === 204) return null;
    if (!response.body) throw new PullRequestError("malformed_response");
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let raw = "";
    let bytes = 0;
    try {
      while (true) {
        const chunk = await reader.read();
        if (chunk.done) break;
        bytes += chunk.value.byteLength;
        if (bytes > 1_000_000) throw new PullRequestError("response_limit_exceeded");
        raw += decoder.decode(chunk.value, { stream: true });
      }
      raw += decoder.decode();
    } finally { reader.releaseLock(); }
    if (!raw && method !== "GET") return null;
    try { return JSON.parse(raw) as unknown; } catch { throw new PullRequestError("malformed_response"); }
  }
}

function nativeIndex(value: string): number {
  const number = Number(value);
  if (!/^[1-9][0-9]{0,17}$/u.test(value) || !Number.isSafeInteger(number)) throw new PullRequestError("invalid_pr_identity");
  return number;
}

function object(value: unknown, code: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new PullRequestError(code);
  return value as Record<string, unknown>;
}

function sameNativeRepository(value: unknown, repository: RepositoryIdentity): boolean {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const id = (value as Record<string, unknown>).id;
  return repository.provider === "gitea" && Number.isSafeInteger(id) && String(id) === repository.nativeId;
}

function validRefInfo(value: Record<string, unknown>): boolean {
  return typeof value.ref === "string" && validBranchRef(`refs/heads/${value.ref}`) &&
    typeof value.sha === "string" && validRevision(value.sha);
}

function safeUrl(value: unknown, base: URL): boolean {
  if (typeof value !== "string" || value.length > 2048) return false;
  try { const url = new URL(value); return url.origin === base.origin && url.protocol === base.protocol; }
  catch { return false; }
}

function statusState(value: string | undefined): "success" | "failure" | "pending" | "unknown" {
  if (value === "success") return "success";
  if (value === "failure" || value === "error") return "failure";
  if (value === "pending") return "pending";
  return "unknown";
}

function translateHosting(error: unknown): PullRequestError {
  return new PullRequestError(error instanceof Error && "code" in error && typeof error.code === "string"
    ? error.code : "provider_unavailable");
}

    try {
      const adapter = new GiteaPullRequestAdapter({ instanceId: binding.instanceId, baseUrl: binding.baseUrl,
        owner: binding.owner, name: binding.repository,
        token: () => this.options.pullRequestCredentialFor!(binding.credentialRef) });
      const repository = await adapter.repository();
      if (repository.nativeId !== binding.repositoryId) throw new PullRequestError("repository_mismatch");
      const observed = await adapter.read(repository, nativeId);
      if (!observed) throw new ApiError("not_found", "pr_missing", "Pull request is unavailable", false);
      return observed;
    } catch (error) {
      if (error instanceof ApiError) throw error;
      if (error instanceof PullRequestError) throw new ApiError("unavailable", error.code,
        "Pull-request observation is unavailable", true);
      throw error;
    }
  }

  async createRequiredPullRequestDraft(principal: AuthenticatedPrincipal, reportId: string) {
    if (!principal.capabilities.includes("interact") || principal.authKind !== "unix_bearer") {
      throw new ApiError("denied", "pr_operator_required", "Draft creation requires the local operator client", false);
    }
    const publication = this.store.hostingPublications.getByReportId(reportId);
    if (!publication) throw new ApiError("not_found", "publication_unavailable", "Published candidate is unavailable", false);
    if (this.authorizedProjectIds && !this.authorizedProjectIds.has(publication.projectId)) {
      throw new ApiError("denied", "pr_project_denied", "Project is outside the owner scope", false);
    }
    if (!this.options.pullRequestCredentialFor) throw new ApiError("unavailable", "credential_unavailable", "Pull-request credential is unavailable", true);
    const coordinator = new PullRequestDraftCoordinator({
      effects: this.store.pullRequestDrafts,
      publication: (id) => this.store.hostingPublications.getByReportId(id),
      policyRequiresPr: (id) => {
        const policy = this.store.validationEvidenceV2.getPolicy(id);
        return !!policy?.requirements.some((requirement) => requirement.required && requirement.bindings.length > 0 &&
          requirement.bindings.every((binding) => binding.provenance === "external_ci" && binding.event === "pull_request"));
      },
      title: (taskId) => this.store.getTask(taskId).title,
      binding: (projectId, pinned) => pinned
        ? this.store.pullRequestBindings.getRevision(pinned.id, pinned.revision)
        : this.store.pullRequestBindings.list(projectId).find((item) => item.enabled),
      makeAdapter: (binding) => {
        const stored = this.store.pullRequestBindings.getRevision(binding.id, binding.revision);
        if (!stored) throw new PullRequestError("pr_binding_unavailable");
        return new GiteaPullRequestAdapter({ instanceId: stored.instanceId, baseUrl: stored.baseUrl,
          owner: stored.owner, name: stored.repository,
          token: () => this.options.pullRequestCredentialFor!(stored.credentialRef) });
      },
      now: () => this.now().toISOString(), effectId: () => randomUUID()
    });
    try {
      const result = await coordinator.create(reportId);
      return { contractVersion: 1 as const, effectId: result.effectId, reportId: result.reportId,
        projectId: result.projectId, taskId: result.taskId, bindingId: result.bindingId,
        bindingRevision: result.bindingRevision, headRef: result.headRef, headRevision: result.headRevision,
        baseRef: result.baseRef, state: result.state, ...(result.nativePrId ? { nativePrId: result.nativePrId } : {}),
        recordedAt: result.recordedAt, updatedAt: result.updatedAt };
    } catch (error) {
      if (!(error instanceof PullRequestError)) throw error;
      const category = error.code.endsWith("outcome_unknown") ? "recovery_required" :
        error.code === "credential_unavailable" || error.code === "provider_unavailable" ? "unavailable" :
        error.code === "publication_unavailable" || error.code === "pr_binding_unavailable" ? "not_found" : "invalid";
      throw new ApiError(category, error.code, "Pull-request draft could not be confirmed", category === "unavailable");
    }
  }

  configureHostingBinding(principal: AuthenticatedPrincipal, input: HostingBindingConfiguration, expectedRevision: number) {
    if (!principal.capabilities.includes("interact") || principal.authKind !== "unix_bearer") {
      throw new ApiError("denied", "hosting_operator_required", "Hosting configuration requires the local operator client", false);
    }
    if (this.authorizedProjectIds && !this.authorizedProjectIds.has(input.projectId)) throw new ApiError("denied", "hosting_project_denied", "Project is outside the owner scope", false);
    if (!this.store.hasRegisteredProject(input.projectId)) throw new ApiError("not_found", "hosting_project_missing", "Project is unavailable", false);
    try { return projectHostingBinding(this.store.hostingBindings.configure(input, expectedRevision, this.now().toISOString())); }
